def tek_dongu(n):
    adim = 0
    for i in range(n):
        adim += 1
    return adim

def ic_ice(n):
    adim = 0
    for i in range(n):
        for j in range(i, n):
            adim += 1
    return adim

for n in (4, 8, 16):
    print(n, tek_dongu(n), ic_ice(n), round(ic_ice(n) / tek_dongu(n), 2))

